// Real-run replay data for scenario guides: the original DeTars run behind each guide, compressed
// to phases, colleague lanes, sources and a few key judgments, plus a request form pre-filled with
// the original user's situation. Data is generated by scripts/scenarios/build-replays.mjs.
import type { AnyLocale } from "@/lib/site";

export type ReplayField = { key: string; label: string; value: string; placeholder?: string };
export type ReplayText = {
  askTitle: string; runTitle: string; fields: ReplayField[]; template: string;
  phases: { title: string; note?: string; judgment?: string }[];
  workers: string[]; chipNames: Record<string, string>;
};
export type ReplayPhase = {
  start: number; end: number; chips: string[];
  workers: { n: number; minutes: number; parallel: boolean; review: boolean }[];
};
export type ReplayStats = { searches: number | null; pages: number | null; colleagues: number; parallel: number; reviewer: boolean };
export type ScenarioReplayData = {
  slug: string; startedAt: string; activeSec: number; stats: ReplayStats; phases: ReplayPhase[]; text: Partial<Record<AnyLocale, ReplayText>>;
};

const files = import.meta.glob<ScenarioReplayData>("../data/scenario-replays/*.json", { eager: true, import: "default" });
const bySlug = new Map(Object.values(files).map((data) => [data.slug, data]));

export function scenarioReplay(slug: string, locale: AnyLocale): { data: ScenarioReplayData; text: ReplayText } | undefined {
  const data = bySlug.get(slug);
  const text = data?.text[locale];
  return data && text ? { data, text } : undefined;
}

export type ReplayCopy = {
  askEyebrow: string; askSub: string; copy: string; copied: string; copyFail: string; seeRun: string;
  runEyebrow: string; play: string; playing: string; replay: string; colleague: string; parallel: string;
  review: string; judgment: string; minutes: (n: number) => string; divider: string; formLabel: string;
  summary: (activeSec: number, s: ReplayStats) => string[];
};

const hm = (sec: number, h: string, m: string, sep: string) => {
  const mins = Math.max(1, Math.round(sec / 60));
  return mins >= 60 ? `${Math.floor(mins / 60)}${h}${sep}${mins % 60}${m}` : `${mins}${m}`;
};

const copies: Partial<Record<AnyLocale, ReplayCopy>> = {
  en: {
    askEyebrow: "Use your own situation",
    askSub: "Edit the fields and the request updates. They are pre-filled with the situation from the original run; empty ones were not mentioned then, so follow the grey example.",
    copy: "Copy request", copied: "Copied. Paste it into DeTars to run it.", copyFail: "Copy failed; select the text above by hand.",
    seeRun: "See the real run first ↓", runEyebrow: "A real run", play: "▶ Replay", playing: "Playing…", replay: "↺ Replay",
    colleague: "Colleague", parallel: "in parallel", review: "review", judgment: "Key judgment",
    minutes: (n) => `${n} min`, divider: "Below is the guide this run delivered", formLabel: "Your request",
    summary: (sec, s) => [
      `${hm(sec, " h", " min", " ")} of active work`,
      ...(s.searches ? [`${s.searches} searches`] : []),
      ...(s.pages ? [`${s.pages} web pages read`] : []),
      ...(s.colleagues ? [`${s.colleagues} ${s.colleagues === 1 ? "colleague" : "colleagues"}${s.parallel > 1 ? `, ${s.parallel} working in parallel` : ""}${s.reviewer ? ", then an independent check" : ""}`] : []),
    ],
  },
  zh: {
    askEyebrow: "换成你的情况",
    askSub: "改下面的格子，请求会跟着变。已经填好的是这篇文章原始运行时那位用户的情况；空着的格子是他当时没提到的，可以照灰色示例填。",
    copy: "复制请求", copied: "已复制，粘到 DeTars 里就能开跑。", copyFail: "复制没成功，请手动选中上面的文字。",
    seeRun: "先看一次真实运行 ↓", runEyebrow: "一次真实运行", play: "▶ 回放", playing: "播放中…", replay: "↺ 重播",
    colleague: "同事", parallel: "同时进行", review: "复核", judgment: "关键判断",
    minutes: (n) => `${n} 分钟`, divider: "下面是这次运行交付的文章原文", formLabel: "你的请求",
    summary: (sec, s) => [
      `实际干活 ${hm(sec, " 小时", " 分钟", " ")}`,
      ...(s.searches ? [`搜索 ${s.searches} 次`] : []),
      ...(s.pages ? [`读了 ${s.pages} 个网页`] : []),
      ...(s.colleagues ? [`${s.colleagues} 位同事${s.parallel > 1 ? `，其中 ${s.parallel} 位同时进行` : ""}${s.reviewer ? "，最后独立复核" : ""}`] : []),
    ],
  },
};

export const replayCopy = (locale: AnyLocale): ReplayCopy | undefined => copies[locale];

export function clock(sec: number): string {
  const s = Math.max(0, Math.round(sec));
  return `${String(Math.floor(s / 60)).padStart(2, "0")}:${String(s % 60).padStart(2, "0")}`;
}
